package com.ancu.proptech.service.billing;
import com.ancu.proptech.dto.billing.BillingContext;
import com.ancu.proptech.exception.common.ApiException;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.json.JsonMapper;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
class UtilityInvoiceAiServiceTests {
 private final JsonMapper json=JsonMapper.builder().build();
 private BillingContext context(){var c=mock(BillingContext.class);when(c.contractId()).thenReturn(42L);when(c.roomNumber()).thenReturn("P101");when(c.period()).thenReturn("2026-11");when(c.electricityStartReading()).thenReturn("100");when(c.waterStartReading()).thenReturn("10");when(c.waterBillingMode()).thenReturn("METERED");return c;}
 private String response(String room,String electricity,String water){return "{\"roomNumber\":"+room+",\"electricityEndReading\":"+electricity+",\"waterEndReading\":"+water+"}";}
 @Test void explicitRoomAndBothEndReadingsProduceOnlyAValidatedSuggestion(){var result=UtilityInvoiceAiService.validate(context(),"Phòng P101, chỉ số điện cuối 150, nước cuối 20",json.readTree(response("\"P101\"","\"150\"","\"20\"")));assertEquals("150",result.electricityEndReading());assertEquals("20",result.waterEndReading());assertEquals("42",result.contractId());}
 @Test void missingRoomOrMissingReadingsNeverCreatesAnInvoice(){for(String data:new String[]{response("null","\"150\"","\"20\""),response("\"P101\"","null","\"20\""),response("\"P101\"","\"150\"","null")}){var e=assertThrows(ApiException.class,()->UtilityInvoiceAiService.validate(context(),"P101 điện 150 nước 20",json.readTree(data)));assertEquals("INVOICE_INPUT_REQUIRED",e.code);}}
 @Test void anotherRoomAndFabricatedProviderNumbersAreRejected(){assertThrows(ApiException.class,()->UtilityInvoiceAiService.validate(context(),"P102 điện 150 nước 20",json.readTree(response("\"P102\"","\"150\"","\"20\""))));assertThrows(ApiException.class,()->UtilityInvoiceAiService.validate(context(),"P101 điện 150 nước 20",json.readTree(response("\"P101\"","\"999\"","\"20\""))));}
 @Test void decreasingOrMalformedReadingsAreRejected(){for(String value:new String[]{"99","-1","1e6","150.001"})assertThrows(ApiException.class,()->UtilityInvoiceAiService.validate(context(),"P101 điện "+value+" nước 20",json.readTree(response("\"P101\"","\""+value+"\"","\"20\""))));}
 @Test void perPersonWaterKeepsExistingBaseline(){var c=context();when(c.waterBillingMode()).thenReturn("PER_PERSON");var result=UtilityInvoiceAiService.validate(c,"P101 điện cuối 150",json.readTree(response("\"P101\"","\"150\"","null")));assertEquals("10",result.waterEndReading());}
 @Test void digitsInRoomNumberCannotBeUsedAsMissingMeterReadings(){assertThrows(ApiException.class,()->UtilityInvoiceAiService.validate(context(),"Phòng P101 nước cuối 20",json.readTree(response("\"P101\"","\"101\"","\"20\""))));}
 @Test void authorizationFailureDoesNotCallAi(){var invoices=mock(InvoiceService.class);var ai=mock(com.ancu.proptech.service.ai.AssistanceClient.class);var jwt=org.springframework.security.oauth2.jwt.Jwt.withTokenValue("fixture").header("alg","none").subject("1").build();when(invoices.context(jwt,42L)).thenThrow(new ApiException(org.springframework.http.HttpStatus.NOT_FOUND,"RESOURCE_NOT_FOUND","Unavailable"));var service=new UtilityInvoiceAiService(invoices,ai,new com.ancu.proptech.service.ai.AssistanceLimit(),json);assertThrows(ApiException.class,()->service.suggest(jwt,42L,new com.ancu.proptech.dto.billing.UtilityInvoiceAiDtos.Command("P101 điện 150 nước 20","2026-11",0)));verifyNoInteractions(ai);}
 @Test void staleBillingPeriodDoesNotCallAi(){var invoices=mock(InvoiceService.class);var ai=mock(com.ancu.proptech.service.ai.AssistanceClient.class);var jwt=org.springframework.security.oauth2.jwt.Jwt.withTokenValue("fixture").header("alg","none").subject("1").build();var billing=context();when(invoices.context(jwt,42L)).thenReturn(billing);var service=new UtilityInvoiceAiService(invoices,ai,new com.ancu.proptech.service.ai.AssistanceLimit(),json);assertThrows(ApiException.class,()->service.suggest(jwt,42L,new com.ancu.proptech.dto.billing.UtilityInvoiceAiDtos.Command("P101 điện 150 nước 20","2026-10",0)));verifyNoInteractions(ai);}
}
